function store_tab_fields(string $tab): array { $out=[];foreach(store_tab_schema()[$tab]??[] as $fields)foreach($fields as $f)$out[$f['key']]=$f;return $out; }
function admin_store_settings_tab(string $tab): void {
    $labels=store_tab_labels();$labels['shipping-options']='Shipping settings';if(!isset($labels[$tab])){http_response_code(404);exit('Settings tab not found.');}
    if($tab==='site-visibility'){admin_store_visibility();return;}
    if($tab==='order-statuses'){admin_store_order_statuses();return;}
    $schema=store_tab_schema()[$tab]??[];
    $values=[];foreach(store_tab_fields($tab) as $key=>$field)$values[$key]=store_option($key);
    $pages=rows("SELECT ID,post_title FROM wp_posts WHERE post_type='page' AND post_status IN ('publish','private','draft') ORDER BY post_title LIMIT 1000");
    admin_layout(($tab==='shipping-options'?$labels[$tab]:$labels[$tab].' settings'),static function() use($tab,$labels,$schema,$values,$pages){store_header($labels[$tab],$tab==='shipping-options'?'shipping':$tab);if($tab==='tax'): ?><nav class="store-subtabs"><a class="active" href="<?=h(path(store_tab_route('tax')))?>">Tax options</a><a href="<?=h(path('/admin/woocommerce/tax'))?>">Standard rates</a><a href="<?=h(path('/admin/woocommerce/tax'))?>">Zero rate rates</a></nav><?php endif; if($tab==='shipping-options') store_shipping_subtabs('options'); if($tab==='email'): $notices=rows("SELECT option_name,option_value FROM wp_options WHERE option_name LIKE 'woocommerce_%_settings' AND (option_name LIKE '%order%settings' OR option_name LIKE '%customer%settings') ORDER BY option_name"); ?><section class="store-card"><h2>Email notifications</h2><table class="store-table"><thead><tr><th>Email</th><th>Status</th></tr></thead><tbody><?php foreach($notices as $n): $v=@unserialize($n['option_value'],['allowed_classes'=>false]);if(!is_array($v)||!isset($v['enabled']))continue; ?><tr><td><?=h(ucwords(str_replace('_',' ',preg_replace('/^woocommerce_|_settings$/','',$n['option_name']))))?></td><td><?=($v['enabled']==='yes')?'Enabled':'Disabled'?></td></tr><?php endforeach; ?></tbody></table></section><?php endif; ?><form method="post" action="<?=h(path('/admin/woocommerce/settings/tab'))?>"><?=csrf_field()?><input type="hidden" name="tab" value="<?=h($tab)?>"><?php foreach($schema as $section=>$fields): ?><section class="store-card store-settings-section"><h2><?=h($section)?></h2><div class="store-settings-rows"><?php foreach($fields as $field): $key=$field['key'];$value=is_scalar($values[$key]??null)?(string)$values[$key]:''; ?><div class="store-settings-row"><label for="<?=h($key)?>"><?=h($field['label'])?></label><div><?php if($field['type']==='check'): ?><input id="<?=h($key)?>" type="checkbox" name="<?=h($key)?>" value="yes" <?=$value==='yes'?'checked':''?>><?php elseif($field['type']==='textarea'): ?><textarea id="<?=h($key)?>" name="<?=h($key)?>" rows="4" maxlength="5000"><?=h($value)?></textarea><?php elseif($field['type']==='select'): ?><select id="<?=h($key)?>" name="<?=h($key)?>"><?php foreach($field['choices'] as $choice=>$name): ?><option value="<?=h($choice)?>" <?=$value===(string)$choice?'selected':''?>><?=h($name)?></option><?php endforeach; ?></select><?php elseif($field['type']==='page'): ?><select id="<?=h($key)?>" name="<?=h($key)?>"><option value="0">— Select a page —</option><?php foreach($pages as $p): ?><option value="<?=h($p['ID'])?>" <?=$value===(string)$p['ID']?'selected':''?>><?=h($p['post_title']?:'Untitled #'.$p['ID'])?></option><?php endforeach; ?></select><?php elseif($field['type']==='secret'): ?><input id="<?=h($key)?>" name="<?=h($key)?>" type="password" value="" placeholder="<?=($value!=='')?'Saved — leave blank to keep':'Enter license key'?>" autocomplete="new-password"><small>Stored value is never shown.</small><?php else: ?><input id="<?=h($key)?>" name="<?=h($key)?>" type="<?=in_array($field['type'],['number','email','color'],true)?h($field['type']):'text'?>" value="<?=h($value)?>" maxlength="5000" <?=$field['type']==='number'?'min="0"':''?>><?php endif; ?></div></div><?php endforeach; ?></div></section><?php endforeach; ?><button class="primary">Save changes</button></form><link rel="stylesheet" href="<?=h(path('/assets/store-config.css'))?>"><?php });
}
function store_shipping_subtabs(string $active): void { ?><nav class="store-subtabs" aria-label="Shipping sections"><?php foreach(['zones'=>['Shipping zones','/admin/woocommerce/shipping'],'options'=>['Shipping settings','/admin/woocommerce/settings?tab=shipping-options'],'classes'=>['Classes','/admin/woocommerce/shipping-classes']] as $key=>$item): ?><a class="<?=$active===$key?'active':''?>" href="<?=h(path($item[1]))?>"><?=h($item[0])?></a><?php endforeach; ?></nav><?php }
function admin_store_shipping_classes(): void {
    $items=rows("SELECT t.term_id,t.name,t.slug,tt.description,tt.count FROM wp_terms t JOIN wp_term_taxonomy tt ON tt.term_id=t.term_id WHERE tt.taxonomy='product_shipping_class' ORDER BY t.name");
    admin_layout('Shipping classes',static function() use($items){store_header('Shipping','shipping');store_shipping_subtabs('classes');?><div class="store-card"><h2>Shipping classes</h2><table class="store-table"><thead><tr><th>Shipping class</th><th>Slug</th><th>Description</th><th>Product count</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><?=h($i['name'])?></td><td><?=h($i['slug'])?></td><td><?=h($i['description'])?></td><td><?=h($i['count'])?></td></tr><?php endforeach; if(!$items): ?><tr><td colspan="4">No shipping classes have been created.</td></tr><?php endif; ?></tbody></table></div><link rel="stylesheet" href="<?=h(path('/assets/store-config.css'))?>"><?php });
}
function save_store_settings_tab(): never {
    $tab=(string)($_POST['tab']??'');$fields=store_tab_fields($tab);if(!$fields){http_response_code(400);exit('Invalid settings tab.');}
    $changes=[];foreach($fields as $key=>$field){$type=$field['type'];$value=$type==='check'?(isset($_POST[$key])?'yes':'no'):trim((string)($_POST[$key]??''));if($type==='secret'&&$value==='')continue;if(mb_strlen($value)>5000){notice('A value is too long.');redirect(store_tab_route($tab));}if($type==='number'&&$value!==''&&(!ctype_digit($value)||strlen($value)>12)){notice('Enter a valid number.');redirect(store_tab_route($tab));}if($type==='email'&&$value!==''&&!filter_var($value,FILTER_VALIDATE_EMAIL)){notice('Enter a valid email address.');redirect(store_tab_route($tab));}if($type==='select'&&!array_key_exists($value,$field['choices'])){notice('Select a valid option.');redirect(store_tab_route($tab));}if($type==='page'&&$value!=='0'&&!row("SELECT ID FROM wp_posts WHERE ID=? AND post_type='page'",[(int)$value])){notice('Select a valid page.');redirect(store_tab_route($tab));}if($type==='color'&&$value!==''&&!preg_match('/^#[0-9a-fA-F]{6}$/',$value)){notice('Enter a valid color.');redirect(store_tab_route($tab));}$changes[$key]=$value;}
    db()->beginTransaction();try{foreach($changes as $key=>$value)store_put_option($key,$value);audit_change('woocommerce_settings',0,'update_tab',[],['tab'=>$tab,'keys'=>array_keys($changes)]);db()->commit();}catch(Throwable $e){db()->rollBack();throw $e;}
    notice('Settings saved.');redirect(store_tab_route($tab));
}
function admin_store_visibility(): void {
    $v=(string)(store_option('blog_public')??'1');admin_layout('Site visibility',static function() use($v){store_header('Site visibility','site-visibility');?><form class="store-card store-form" method="post" action="<?=h(path('/admin/woocommerce/visibility'))?>"><?=csrf_field()?><h2>Store visibility</h2><label class="store-check"><input type="radio" name="visible" value="1" <?=$v==='1'?'checked':''?>> Live</label><label class="store-check"><input type="radio" name="visible" value="0" <?=$v==='0'?'checked':''?>> Discourage search engines from indexing</label><button class="primary">Save changes</button></form><p class="store-help">This setting mirrors the imported WordPress option. The custom storefront visibility must be configured separately.</p><link rel="stylesheet" href="<?=h(path('/assets/store-config.css'))?>"><?php });
}
function save_store_visibility(): never {$v=(string)($_POST['visible']??'');if(!in_array($v,['0','1'],true)){http_response_code(400);exit('Invalid visibility.');}db()->beginTransaction();try{store_put_option('blog_public',$v);audit_change('woocommerce_settings',0,'visibility',[],['value'=>$v]);db()->commit();}catch(Throwable $e){db()->rollBack();throw $e;}notice('Visibility setting saved.');redirect(store_tab_route('site-visibility'));}
function admin_store_order_statuses(): void {
    $items=rows("SELECT ID,post_title,post_name,post_status,menu_order FROM wp_posts WHERE post_type='wc_order_status' ORDER BY menu_order,ID");
    admin_layout('Order Statuses',static function() use($items){store_header('Order Statuses','order-statuses');?><div class="store-card"><table class="store-table"><thead><tr><th>Name</th><th>Slug</th><th>Status</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><?=h($i['post_title'])?></td><td><?=h($i['post_name'])?></td><td><?=h($i['post_status'])?></td></tr><?php endforeach; if(!$items): ?><tr><td colspan="3">No custom order statuses found.</td></tr><?php endif; ?></tbody></table></div><link rel="stylesheet" href="<?=h(path('/assets/store-config.css'))?>"><?php });
}
